def _tokens(text):
    out, i, n = [], 0, len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit() or ch == '.':
            j = i
            while j < n and (text[j].isdigit() or text[j] == '.'):
                j += 1
            num = text[i:j]
            out.append(float(num) if '.' in num else int(num))
            i = j
        elif text.startswith('**', i):
            out.append('**')
            i += 2
        elif ch in '+-*/()':
            out.append(ch)
            i += 1
        else:
            raise ValueError(f'bad character {ch!r}')
    return out


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expr(self):
        value = self.term()
        while self.peek() in ('+', '-'):
            op = self.take()
            right = self.term()
            value = value + right if op == '+' else value - right
        return value

    def term(self):
        value = self.power()
        while self.peek() in ('*', '/'):
            op = self.take()
            right = self.power()
            value = value * right if op == '*' else value / right
        return value

    def power(self):
        value = self.atom()
        while self.peek() == '**':
            self.take()
            value = value ** self.atom()
        return value

    def atom(self):
        tok = self.take()
        if tok == '-':
            return -self.atom()
        if tok == '(':
            value = self.expr()
            if self.take() != ')':
                raise ValueError('expected )')
            return value
        if isinstance(tok, (int, float)):
            return tok
        raise ValueError('expected a number')


def evaluate(text):
    return _Parser(_tokens(text)).expr()

